"use strict";(globalThis.webpackChunkgrc||=[]).push([[62181],{62299(e){e.exports=JSON.parse('{"citeKey":"logan2024evaluationdaos","slug":"logan-2024-evaluation-daos-6eb2","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"SIGOPS Operating Systems Review (OSR\'24)","type":"Journal","entryType":"article","date":"June, 2024","year":2024,"era":"iit","month":6,"doi":"10.1145/3689051.3689058","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-evaluation-daos-6eb2.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","titleQualifier":"Journal 2024","projectIds":["iowarp","deepio"],"memberAuthors":["logan-luke","lofstead-jay","kougkas-anthony","sun-xian-he"]}')}}]);